{
if(p==NULL)return;
else
{
cout<<p->data<<end;
TraverseList(p->next);
//递归终止
//输出当前结点的数据域 //p 指向后继指点继续递归
在递归算法中，如果当递归结束条件成立，只执行return 操作时，“分治法”求解递归问题算 法的一般形式可以简化为：
void p(参数表)
{
if(递归结束条件不成立)
p (较小的参数);
}
因此，算法3.9可以简化为：
void TraverseList(LinkList p)
{
if(p)
{
cout<<p->data<<end;
TraverseList(p->next);
}
}
